import{exerciseData,recoveryData}from './resp-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const rt=(x,y,s,size=19)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${size}">${esc(s)}</text>`;
export const respSVG=(art,label)=>`<svg class="shell-diagram resp-diagram" viewBox="0 0 560 400" role="img" aria-label="${esc(label)}">${art}</svg>`;
export function respTable(rows,heads){return '<table class="photo-data resp-data"><thead><tr>'+heads.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
export function respFigure(w={}){let s=w.state||'oxygen',k=w.kind||'mitochondrion',body='',caption=w.result||'Symbolic geometry and original data; use the labels.';
if(k==='exercise'){body=respTable(exerciseData.map(d=>[d.label,d.pulse,d.breaths,d.volume]),['State','beats/min','breaths/min','L/breath']);return body+'<p class="diagram-caption">'+esc(caption)+'</p>';}
if(k==='recovery-data')return respTable(recoveryData.map((d,i)=>[i+1,d.rate,d.baseline,d.minutes]),['Interval','Use L/min','Rest L/min','min'])+'<p class="diagram-caption">Each interval has the stated constant rate; original data.</p>';
if(k==='mitochondrion'){body='<ellipse cx="280" cy="190" rx="205" ry="100" fill="#b99d8a" stroke="#edc6a8" stroke-width="5"/><path d="M120 190q35-120 65 0t65 0t65 0t65 0t65 0" fill="none" stroke="#ecd8b7" stroke-width="9"/>'+rt(280,45,'Mitochondrion · enlarged folds',23)+rt(280,335,s==='no-oxygen'?'Oxygen absent: aerobic route unavailable':'Glucose + oxygen → CO₂ + water',22);}
else if(k==='heat'){let temp=s==='killed'?12:18;body='<path d="M100 120V300H240V120M320 120V300H460V120" stroke="#bed1cc" stroke-width="5" fill="#9fb9b522"/><path d="M170 280V95M390 280V95" stroke="#f0dfc6" stroke-width="12"/><path d="M170 280V'+(s==='killed'?210:145)+'M390 280V210" stroke="#edab94" stroke-width="7"/>'+rt(170,65,temp+'°C',25)+rt(390,65,'12°C',25)+rt(170,340,s==='killed'?'Killed sample':'Living sample',19)+rt(390,340,'Killed control',19);}
else if(k==='recovery'){let labels=['Muscle','Blood','Liver','Glucose'],n=Math.min(3,w.step??(s==='conversion'?2:0));body=labels.map((x,i)=>`<rect x="${30+i*130}" y="140" width="110" height="80" rx="18" fill="${i===n?'#b48b75':'#35536a'}" stroke="#bfd2ce"/>`+rt(85+i*130,187,x,19)+(i<3?`<path d="M${142+i*130} 180h14l-5-5m5 5l-5 5" stroke="#eed4ab" fill="none"/>`:'')).join('')+rt(280,80,'Lactic acid transport and conversion',23)+rt(280,315,'Higher · route summary, not biochemical detail',18);}
else if(k==='fermentation'){let muscle=s==='muscle',bread=s==='bread',drink=s==='drink';body=(muscle?'<ellipse cx="280" cy="195" rx="200" ry="100" fill="#a1746c" stroke="#e7b7a2" stroke-width="4"/>':'<path d="M180 120V75H380V120l40 150q10 40-40 40H180q-50 0-40-40z" fill="#a8c2c62a" stroke="#c1d7d4" stroke-width="4"/>')+rt(280,180,muscle?'Muscle cell':'Plant / yeast cell',23)+rt(280,245,muscle?'Lactic acid':'Ethanol + CO₂',23)+rt(280,360,bread?'CO₂ makes dough rise':drink?'Ethanol is the alcohol product':'Glucose is incompletely oxidised',21);}
else if(k==='yield'){body=rt(280,65,'Same glucose input · qualitative comparison',22);for(let i=0;i<(s==='anaerobic'?2:8);i++)body+=`<circle cx="${110+i%4*110}" cy="${160+Math.floor(i/4)*90}" r="28" fill="#d8b58e"/>`;body+=rt(280,355,s==='anaerobic'?'Much less energy transferred':'Much more energy transferred',23);}
else if(k==='lipid'){let g=Number(w.glycerol??1),f=Number(w.fatty??3);body=rt(280,65,'1 glycerol + 3 fatty acids → lipid',24);for(let i=0;i<Math.min(3,g);i++)body+=`<rect x="${80+i*35}" y="140" width="25" height="125" rx="8" fill="#a7c4c5"/>`;for(let i=0;i<Math.min(5,f);i++)body+=`<path d="M220 ${125+i*40}h220" stroke="#deb694" stroke-width="14"/>`;body+=rt(280,365,'Building-block model, not a molecular structure',18);}
else if(k==='muscle'){body='<path d="M85 125Q280 65 475 125V275Q280 335 85 275Z" fill="#a1746c" stroke="#e7b7a2" stroke-width="4"/>'+Array.from({length:8},(_,i)=>`<path d="M${130+i*42} 130v140" stroke="#d9b8a2" stroke-width="4"/>`).join('')+rt(280,55,s==='insufficient'?'Oxygen supply cannot meet demand':'Oxygen supply meets demand',22)+rt(280,365,s==='insufficient'?'Anaerobic contribution; fatigue can develop':'Aerobic respiration supports muscle work',20);}
else if(k==='energy'){body='<ellipse cx="280" cy="180" rx="110" ry="70" fill="#b19782"/>'+rt(280,185,'Respiration',22)+'<path d="M280 260v50m-10-10l10 10l10-10" stroke="#edc99d" stroke-width="4" fill="none"/>'+rt(280,355,{synthesis:'Build larger molecules',movement:'Movement',warmth:'Keeping warm'}[s]||'Energy for living processes',24);}
else {let names={starch:'Glucose → starch',glycogen:'Glucose → glycogen',cellulose:'Glucose → cellulose',protein:'Amino acids ↔ protein',urea:'Excess protein nitrogen → urea',lipid:'Glycerol + fatty acids ↔ lipid',carbohydrate:'Sugars ↔ carbohydrate'};body=rt(280,55,names[s]||'Metabolic synthesis and breakdown',22)+'<circle cx="100" cy="190" r="48" fill="#b9a185"/><path d="M170 190h170l-12-10m12 10l-12 10" stroke="#efcda4" stroke-width="4" fill="none"/><rect x="380" y="130" width="95" height="120" rx="24" fill="#9dbcb4"/>'+rt(280,335,'Enzyme-controlled reactions; respiration supplies energy',18);}
return respSVG(body,w.title||k)+'<p class="diagram-caption">'+esc(caption)+'</p>';}
